<?php
require_once '../config.php'; header('Content-Type: application/json; charset=utf-8'); $userId=requireAuth();
$in=json_decode(file_get_contents('php://input'),true)?:[];$id=intval($in['idea_id']??0);$day=max(1,min(30,intval($in['current_day']??1)));$status=in_array($in['status']??'active',['active','paused','completed'],true)?$in['status']:'active';$notes=mb_substr(trim((string)($in['notes']??'')),0,12000);$voice=mb_substr(trim((string)($in['voice_transcript']??'')),0,12000);
if(!$id){http_response_code(400);echo json_encode(['success'=>false,'message'=>'Ideia inválida.']);exit;}
try{$db=getDBConnection();$check=$db->prepare('SELECT id FROM ideas WHERE id=? AND user_id=?');$check->execute([$id,$userId]);if(!$check->fetch()){http_response_code(404);echo json_encode(['success'=>false,'message'=>'Ideia não encontrada.']);exit;}$q=$db->prepare("INSERT INTO idea_progress (idea_id,user_id,current_day,status,notes,voice_transcript,updated_at) VALUES (?,?,?,?,?,?,NOW()) ON CONFLICT (idea_id,user_id) DO UPDATE SET current_day=EXCLUDED.current_day,status=EXCLUDED.status,notes=EXCLUDED.notes,voice_transcript=EXCLUDED.voice_transcript,updated_at=NOW() RETURNING id,idea_id,current_day,status,notes,voice_transcript,updated_at");$q->execute([$id,$userId,$day,$status,$notes,$voice]);echo json_encode(['success'=>true,'progress'=>$q->fetch()],JSON_UNESCAPED_UNICODE);}catch(Exception $e){error_log('Erro save-progress: '.$e->getMessage());http_response_code(500);echo json_encode(['success'=>false,'message'=>'Não foi possível guardar o progresso.']);}
?>